-- SPeditor — the guides of the editor itself (Help → How to use, cl_ui_guide.lua).
-- The guides of SAeditor are in its own folder (cl_saeditor_guides.lua).
local UI = SPeditor.UI
local C  = SPeditor.Client

UI.AddGuide({ id = "start", order = 1, title = { en = "Your first scene", ru = "Первая сцена" }, blocks = {
	{ "p", "A scene is models, lights and cameras placed in the map. You pose them, light them and render a picture — as in Source Filmmaker, but inside the running game.",
		"Сцена — это модели, свет и камеры, расставленные на карте. Их позируют, освещают и рендерят в картинку — как в Source Filmmaker, только прямо в запущенной игре." },
	{ "img", "speditor/help/overview.jpg", "The editor: the Animation Set Editor on the left, the viewports in the middle, the timeline and the scene list at the bottom.",
		"Редактор: слева Animation Set Editor, в середине вьюпорты, внизу таймлайн и список сцен." },
	{ "steps",
		en = { "Add a character: the + button of the Animation Set Editor → Model…, or Windows → Model Browser. Double click a model to place it in front of the camera.",
			"Look around in the Primary Viewport: hold the right mouse button and fly with W A S D (Q / E — down / up); Alt + left mouse — orbit around the selection; the wheel — closer / farther; F — look at the selection.",
			"Click the character, then click a bone (the dots of its skeleton) and turn it with the rotate tool (2). Ctrl + Z undoes anything.",
			"Add a light (+ → Spawn spot light in front) and a camera (+ → Spawn Camera), place them like any object.",
			"File → Save scene… keeps everything; Render (top right) makes the picture." },
		ru = { "Добавьте персонажа: кнопка + в Animation Set Editor → Модель…, или Окна → Браузер моделей. Двойной клик по модели ставит её перед камерой.",
			"Осмотритесь в основном вьюпорте: зажмите правую кнопку мыши и летите на W A S D (Q / E — вниз / вверх); Alt + левая кнопка — облёт вокруг выделенного; колесо — ближе / дальше; F — показать выделенное.",
			"Щёлкните персонажа, затем кость (точки его скелета) и поверните её инструментом поворота (2). Ctrl + Z отменяет что угодно.",
			"Добавьте свет (+ → Прожектор перед камерой) и камеру (+ → Создать камеру) и расставьте их, как любой объект.",
			"Файл → Сохранить сцену… сохраняет всё; Рендер (справа вверху) делает картинку." } },
	{ "img", "speditor/help/browser.jpg", "The model browser: search, categories, addons and games the models come from.", "Браузер моделей: поиск, категории, аддоны и игры, из которых модели." },
	{ "result", "A saved scene with a posed character, light and a camera, ready to render or animate.",
		"Сохранённая сцена с позированным персонажем, светом и камерой — её можно рендерить или анимировать." },
	{ "try", "Open the model browser", "Открыть браузер моделей", fn = function() UI.ToggleBrowser() end },
} })

UI.AddGuide({ id = "posing", order = 2, title = { en = "Posing: move, turn, IK, locks", ru = "Позирование: перенос, поворот, IK, замки" }, blocks = {
	{ "p", "The gizmo moves (1), turns (2) and scales (4) what is selected — the whole object or one bone. 3 switches between the world axes and the object's own.",
		"Гизмо переносит (1), поворачивает (2) и масштабирует (4) выделенное — весь объект или одну кость. 3 переключает мировые оси и собственные оси объекта." },
	{ "h", "Turning freely", "Свободный поворот" },
	{ "img", "speditor/help/gizmo_rotate.jpg", "The rotate gizmo: three coloured rings turn around one axis each; the white outer ring turns around the line of sight; anywhere inside the rings is a trackball.",
		"Гизмо поворота: три цветных кольца поворачивают каждое вокруг своей оси; белое внешнее кольцо — вокруг линии взгляда; всё внутри колец — трекбол." },
	{ "steps",
		en = { "Grab a coloured ring to turn around exactly that axis (hold Shift for fine steps).",
			"Grab the white outer ring to turn the bone as you see it on the screen, like turning a picture.",
			"Grab inside the rings (not on a ring) and drag: the bone rolls after the mouse in every direction at once, like a ball under your hand. A click there without dragging still selects the bone under the cursor." },
		ru = { "Тяните цветное кольцо, чтобы повернуть ровно вокруг этой оси (с Shift — мелкими шагами).",
			"Тяните белое внешнее кольцо, чтобы повернуть кость так, как вы её видите на экране, — как поворачивают картинку.",
			"Тяните внутри колец (не за кольцо): кость катится за мышью во все стороны сразу, как шар под ладонью. Простой щелчок там по-прежнему выделяет кость под курсором." } },
	{ "h", "IK: pull a hand or a foot", "IK: тянуть кисть или стопу" },
	{ "img", "speditor/help/ik.jpg", "With IK on (I) a hand drags its arm: the elbow bends by itself.", "С включённым IK (I) кисть тянет за собой руку: локоть сгибается сам." },
	{ "p", "Turn IK on with I or the button of the viewport bar, select a hand or a foot and move it. Moving the body keeps the feet planted (View → IK: keep the feet planted).",
		"Включите IK клавишей I или кнопкой на панели вьюпорта, выделите кисть или стопу и двигайте. При переносе тела стопы остаются на месте (Вид → IK: стопы стоят на месте)." },
	{ "h", "Bone locks: one hand holds the other", "Замки костей: одна рука держит другую" },
	{ "img", "speditor/help/bone_lock.jpg", "Right click a physical bone → Lock … to bone: the locked bone follows the other one when you pose.",
		"ПКМ по физической кости → Привязать … к кости: привязанная кость следует за другой при позировании." },
	{ "result", "Natural poses in a few drags: free turns with the trackball, limbs that bend by themselves, hands that keep holding things.",
		"Естественные позы за несколько движений: свободные повороты трекболом, конечности сгибаются сами, руки продолжают держать." },
} })

UI.AddGuide({ id = "select", order = 2.5, icon = "icon16/keyboard.png", title = { en = "Selecting, copying, your own keys", ru = "Выделение, копирование, свои клавиши" }, blocks = {
	{ "p", "Several objects can be selected at once: the gizmo then moves, turns and scales them together, and Del, Ctrl + D, copy and paste work on all of them.",
		"Можно выделить сразу несколько объектов: тогда гизмо переносит, поворачивает и масштабирует их вместе, а Del, Ctrl + D, копирование и вставка действуют на все." },
	{ "img", "speditor/help/multiselect.jpg", "Two characters selected: the first one has the gizmo, the other has a frame; both are highlighted in the object list.",
		"Выделены два персонажа: у первого гизмо, у второго рамка; в списке объектов подсвечены оба." },
	{ "steps",
		en = { "Click the first object. Shift + click (or Ctrl + click) others in the viewport or in the object list to add them; Shift + click a selected one takes it out.",
			"Point the cursor at the object list and press Ctrl + A: everything is selected, except locked and hidden objects.",
			"With the cursor over the object list, Ctrl + C copies the selected objects and Ctrl + V pastes copies of them a little aside. Paste again and the next copies go one more step further. One Ctrl + Z takes a whole paste back.",
			"In the viewport Ctrl + C / Ctrl + V still copy and paste a pose. The same commands are in the Edit menu." },
		ru = { "Щёлкните первый объект. Shift + клик (или Ctrl + клик) по другим во вьюпорте или в списке объектов добавляет их; Shift + клик по выделенному убирает его.",
			"Наведите курсор на список объектов и нажмите Ctrl + A: выделится всё, кроме закреплённых и скрытых объектов.",
			"С курсором над списком объектов Ctrl + C копирует выделенные объекты, а Ctrl + V вставляет их копии чуть в стороне. Вставьте ещё раз — следующие копии встанут ещё на шаг дальше. Одно Ctrl + Z убирает всю вставку.",
			"Во вьюпорте Ctrl + C / Ctrl + V по-прежнему копируют и вставляют позу. Те же команды есть в меню «Правка»." } },
	{ "h", "Your own keys", "Свои клавиши" },
	{ "img", "speditor/help/keys.jpg", "View → Interface settings → Keys: every hotkey of the editor and of SAeditor.",
		"Вид → Настройки интерфейса → Клавиши: все горячие клавиши редактора и SAeditor." },
	{ "steps",
		en = { "Open View → Interface settings… → Keys (or Help → Hotkeys → Change keys…).",
			"Click the key of an action and press the new one, with Ctrl / Shift / Alt if you like. Esc cancels. For a click (adding to the selection) hold Shift or Ctrl and click.",
			"A key shown in red is also taken by another action: change one of them. The arrow button returns the default, the cross leaves the action without a key." },
		ru = { "Откройте Вид → Настройки интерфейса… → Клавиши (или Справка → Горячие клавиши → Изменить клавиши…).",
			"Нажмите на клавишу действия и затем новую, если нужно — с Ctrl / Shift / Alt. Esc — отмена. Для клика (добавить к выделению) зажмите Shift или Ctrl и кликните.",
			"Красная клавиша занята ещё каким-то действием — смените одну из них. Кнопка со стрелкой возвращает клавишу по умолчанию, крестик оставляет действие без клавиши." } },
	{ "h", "Interface size", "Размер интерфейса" },
	{ "p", "View → Interface settings → Appearance → Interface scale: from 50 % (more room for the viewports) to 200 % (2K / 4K screens). By default it follows the screen. The windows keep their places when the scale changes.",
		"Вид → Настройки интерфейса → Внешний вид → Масштаб интерфейса: от 50 % (больше места вьюпортам) до 200 % (экраны 2K / 4K). По умолчанию — по экрану. При смене масштаба окна остаются на своих местах." },
	{ "result", "Whole groups posed, moved and copied in a few keystrokes — with the keys you are used to.",
		"Целые группы позируются, двигаются и копируются в пару нажатий — на привычных вам клавишах." },
	{ "try", "Open the key settings", "Открыть настройки клавиш", fn = function() UI.OpenSettings("keys") end },
} })

UI.AddGuide({ id = "lights", order = 3, title = { en = "Light", ru = "Свет" }, blocks = {
	{ "p", "Lights of the editor cast real shadows. A spot light shines through a mask (a texture: a window, leaves, a soft circle); a point light shines everywhere.",
		"Источники света редактора отбрасывают настоящие тени. Прожектор светит через маску (текстуру: окно, листва, мягкий круг); точечный свет светит во все стороны." },
	{ "img", "speditor/help/lights.jpg", "A scene lit by three spot lights: key, fill and back.", "Сцена со светом из трёх прожекторов: рисующий, заполняющий и контровой." },
	{ "steps",
		en = { "+ → Spawn spot light in front puts a light where the camera looks. + → Soft light gives a ready kind (softbox, window light, sun through leaves…).",
			"Select the light: its settings are in the Animation Set Editor — colour, brightness, cone, distance, shadows.",
			"Light mask: the row under the beam settings. Pick an editor mask, a Lamp tool texture, any texture of the game and addons, or type a path (Texture by path).",
			"'source size' (in the light settings) softens the shadows in the render; 'glow size' and 'beam in the air' make the light visible in the picture.",
			"+ → Create 3-point light rig puts key, fill and back lights around the selected character at once." },
		ru = { "+ → Прожектор перед камерой ставит свет туда, куда смотрит камера. + → Мягкий свет даёт готовый вид (софтбокс, свет из окна, солнце сквозь листву…).",
			"Выделите свет: его настройки — в Animation Set Editor: цвет, яркость, конус, дальность, тени.",
			"Маска света: строка под настройками луча. Выберите маску редактора, текстуру инструмента «Лампа», любую текстуру игры и аддонов или введите путь (Текстура по пути).",
			"«размер источника» (в настройках света) смягчает тени в рендере; «ореол» и «луч в воздухе» делают свет видимым в кадре.",
			"+ → Создать трёхточечную схему света сразу ставит рисующий, заполняющий и контровой свет вокруг выделенного персонажа." } },
	{ "img", "speditor/help/light_controls.jpg", "The settings of a light.", "Настройки источника света." },
	{ "result", "Lighting with soft shadows and a shape of your own — the mask decides what the light paints on the walls.",
		"Освещение с мягкими тенями и своей формой — маска решает, какой рисунок свет кладёт на стены." },
} })

UI.AddGuide({ id = "camera", order = 4, title = { en = "Cameras and their effects", ru = "Камеры и их эффекты" }, blocks = {
	{ "p", "A scene camera is the frame of the picture. Depth of field, exposure, vignette, colour curves and shaders belong to a camera and are seen in the Render window and the render.",
		"Камера сцены — это кадр картинки. Глубина резкости, экспозиция, виньетка, цветовые кривые и шейдеры принадлежат камере и видны в окне «Рендер» и в рендере." },
	{ "steps",
		en = { "+ → Spawn Camera puts a camera where you look from. V (or the object menu) looks through it; move the view and the camera moves with it.",
			"Select the camera: its field of view, shake and smoothness are in the Animation Set Editor.",
			"Render window → Camera effects: switch on 'Depth of field of this camera' and set the focus distance (units to what is sharp) and the aperture (how blurry the rest is).",
			"Effects can be animated: change them at another frame with Auto key on (or press K with the camera selected) — the focus moves from one actor to another." },
		ru = { "+ → Создать камеру ставит камеру туда, откуда вы смотрите. V (или меню объекта) — смотреть через неё; двигайте вид — камера движется вместе с ним.",
			"Выделите камеру: её угол обзора, тряска и плавность — в Animation Set Editor.",
			"Окно «Рендер» → Эффекты камеры: включите «Глубина резкости этой камеры» и задайте дистанцию фокуса (единиц до резкого) и диафрагму (насколько размыто остальное).",
			"Эффекты анимируются: измените их на другом кадре с включённым автоключом (или нажмите K при выделенной камере) — фокус переходит с одного актёра на другого." } },
	{ "img", "speditor/help/camera_view.jpg", "Looking through a scene camera.", "Вид через камеру сцены." },
	{ "img", "speditor/help/camera_fx.jpg", "Camera effects in the Render window.", "Эффекты камеры в окне «Рендер»." },
	{ "result", "A frame with a blurred background and a focus that can travel during the animation.",
		"Кадр с размытым фоном и фокусом, который может переходить во время анимации." },
} })

UI.AddGuide({ id = "render", order = 5, title = { en = "Render a picture, Steam screenshots", ru = "Рендер картинки и скриншоты Steam" }, blocks = {
	{ "p", "The Render window shoots the scene off screen at any size, with smoothing, depth of field and soft shadows. A scene with animation renders a video instead (see the SAeditor guides).",
		"Окно «Рендер» снимает сцену вне экрана в любом размере, со сглаживанием, глубиной резкости и мягкими тенями. Сцена с анимацией вместо этого рендерится в видео (см. статьи SAeditor)." },
	{ "img", "speditor/help/render.jpg", "The Render window: settings on the left, the live preview on the right.", "Окно «Рендер»: настройки слева, живой предпросмотр справа." },
	{ "steps",
		en = { "Render (top right) opens the window. Pick the camera, the aspect and the size.",
			"Format: PNG (no loss), JPEG (small files) or Steam screenshot.",
			"Steam screenshot saves the PNG and also puts the picture into your Steam screenshots: the game shows it full screen for a moment and takes a screenshot. Then Steam → View → Screenshots → Garry's Mod → Upload to publish it.",
			"The files are in garrysmod/data/speditor/renders (File → Where are my files)." },
		ru = { "«Рендер» (справа вверху) открывает окно. Выберите камеру, пропорции и размер.",
			"Формат: PNG (без потерь), JPEG (маленькие файлы) или Скриншот Steam.",
			"«Скриншот Steam» сохраняет PNG и ещё кладёт картинку в ваши скриншоты Steam: игра на мгновение показывает её на весь экран и делает скриншот. Затем Steam → Вид → Скриншоты → Garry's Mod → Загрузить — и он опубликован.",
			"Файлы лежат в garrysmod/data/speditor/renders (Файл → Где мои файлы)." } },
	{ "result", "A picture file — and, with the Steam format, a screenshot you can publish on your Steam profile. The Steam copy has the size of your screen.",
		"Файл картинки, а с форматом Steam — ещё и скриншот, который можно опубликовать в профиле Steam. Копия в Steam размером с ваш экран." },
	{ "try", "Open the Render window", "Открыть окно «Рендер»", fn = function() UI.OpenRenderDialog() end },
} })
